        Text({{item.title}}).monarchTextStyle(.bodyStrong)
        Text({{item.description}}).monarchTextStyle(.caption)
        MonarchButton({{item.action}}, variant: .danger) { isOpen = true }
    }
}
.sheet(isPresented: $isOpen) {
    NavigationStack(path: $path) {
        review
            .navigationTitle({{item.action}})
            #if os(iOS)
            .navigationBarTitleDisplayMode(.inline)
            #endif
            .toolbar {
                ToolbarItem(placement: .cancellationAction) { Button("Cancel") { isOpen = false } }
            }
            .navigationDestination(for: String.self) { name in destination(name) }
    }
