        MonarchStepUpAuthDialog(
            description: "Deleting your account needs you to confirm your identity.",
            methods: [{{stepUp.methods.0|case}}, {{stepUp.methods.1|case}}],
            onVerified: {
                // Delete the account on the server here, then sign out.
                isOpen = false
            },
            onVerify: { _ in
                // Send the credential to the server; throw if it is refused.
            }
        )
    }
}

examples.setupTemplate:
@Environment(\.monarchTheme) private var theme
@State private var isOpen = false
@State private var path: [String] = []
@State private var typed = ""
@State private var reason = ""
@State private var isVerifying = false
private let email = {{email}}

private var review: some View {
    ScrollView {
        VStack(alignment: .leading, spacing: theme.spacing.space4) {
            VStack(alignment: .leading, spacing: theme.spacing.space2) {
                Text("Step 1 of 4").monarchTextStyle(.caption).foregroundStyle(theme.colors.textMuted)
                HStack(spacing: theme.spacing.space1) {
                    ForEach(0..<4, id: \.self) { index in
                        Capsule()
                            .fill(index == 0 ? theme.colors.accentSolid : theme.colors.bgMuted)
                            .frame(height: 4)
                    }
                }
                .accessibilityHidden(true)
            }
            Text({{review.title}}).monarchTextStyle(.title)
            Text({{review.description}})
            MonarchConsequenceList(
                [
                    MonarchConsequence({{consequences.0.kind|case}}, {{consequences.0.label}}),
                    MonarchConsequence({{consequences.1.kind|case}}, {{consequences.1.label}}),
                    MonarchConsequence({{consequences.2.kind|case}}, {{consequences.2.label}}),
                ],
                isGrouped: true
            )
            MonarchButton("Continue", variant: .primary, fullWidth: true) { path.append("export") }
        }
        .padding(theme.spacing.space4)
    }
}

private var exportStep: some View {
    VStack(alignment: .leading, spacing: theme.spacing.space4) {
        MonarchDataExportRequest()
        MonarchButton("Continue", variant: .primary, fullWidth: true) { path.append("reason") }
    }
    .padding(theme.spacing.space4)
}

private var reasonStep: some View {
    VStack(alignment: .leading, spacing: theme.spacing.space4) {
        MonarchFormField("Why are you leaving?") {
            Picker("Why are you leaving?", selection: $reason) {
                Text({{reasons.0.label}}).tag({{reasons.0.value}})
                Text({{reasons.1.label}}).tag({{reasons.1.value}})
                Text({{reasons.2.label}}).tag({{reasons.2.value}})
                Text({{reasons.3.label}}).tag({{reasons.3.value}})
            }
            .pickerStyle(.menu)
        }
        MonarchButton("Continue", variant: .primary, fullWidth: true) { path.append("confirm") }
    }
    .padding(theme.spacing.space4)
}

private var confirm: some View {
    VStack(alignment: .leading, spacing: theme.spacing.space4) {
        Text("Your account is deleted permanently. This cannot be undone.").monarchTextStyle(.body)
        MonarchTypeToConfirmInput(phrase: email, text: $typed, label: "Type " + email + " to confirm")
        MonarchButton("Delete account", variant: .danger, fullWidth: true) { isVerifying = true }
            .disabled(!MonarchTypeToConfirmInput.matches(typed, phrase: email))
    }
    .padding(theme.spacing.space4)
}

@ViewBuilder private func destination(_ name: String) -> some View {
    switch name {
    case "export": exportStep
    case "reason": reasonStep
    default: confirm
    }
}

